head.script:
scwin.onpageload = function() {
    var gridStr = '<xf:group tagname="table" id="" style="position:relative;background-color:red;width:400px;height:200px;" class="w2tb" xmlns:xf="http://www.inswave.com/websquare" xmlns:ev="http://www.w3.org/2001/xml-events">' +
        '<thead>' +
        '<tr>' +
        '<td>adasdasd' +
        '</td>' +
        '</tr>' +
        '</thead>' +
        '<tBody>' +
        '<tr>' +
        '<td>adsasdasd' +
        '</td>' +
        '</tr>' +
        '</tBody>' +
        '</xf:group>';
    scwin.$w.dynamicCreate("Tab0_tab1_grd_lineData", "group", WebSquare.xml.parse(gridStr, false), group1);
};
scwin.onpageunload = function() {};
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq(WebSquare.wUnit.getDomById($p.id+'Tab0_tab1_grd_lineData')).children().length == 2", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
